## MVP 架构 Activity 重构成 MVVM + ViewModel + LiveData/StateFlow

以下通过一个登录功能的例子，展示从 MVP 重构为 MVVM 的完整思路。

---

### 1. 原来的 MVP 架构

#### View 层（Activity）

```kotlin
// 定义 View 接口
interface LoginView {
    fun showLoading()
    fun hideLoading()
    fun loginSuccess(user: User)
    fun loginError(message: String)
}

// Activity 实现 LoginView 接口
class LoginActivity : AppCompatActivity(), LoginView {

    private lateinit var presenter: LoginPresenter
    private lateinit var binding: ActivityLoginBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityLoginBinding.inflate(layoutInflater)
        setContentView(binding.root)

        presenter = LoginPresenter(this)

        // 点击登录
        binding.btnLogin.setOnClickListener {
            val username = binding.etUsername.text.toString()
            val password = binding.etPassword.text.toString()
            presenter.login(username, password)
        }
    }

    // 实现 View 接口方法
    override fun showLoading() {
        binding.progress.visibility = View.VISIBLE
    }

    override fun hideLoading() {
        binding.progress.visibility = View.GONE
    }

    override fun loginSuccess(user: User) {
        Toast.makeText(this, "登录成功：${user.name}", Toast.LENGTH_SHORT).show()
    }

    override fun loginError(message: String) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
    }
}
```

#### Presenter 层

```kotlin
class LoginPresenter(private val view: LoginView) {

    private val repository = LoginRepository()

    fun login(username: String, password: String) {
        view.showLoading()
        viewModelScope.launch { // 实际 MVP 常用线程池或自管理协程
            try {
                val user = repository.login(username, password)
                view.loginSuccess(user)
            } catch (e: Exception) {
                view.loginError(e.message ?: "登录失败")
            } finally {
                view.hideLoading()
            }
        }
    }
}
```

